testcase.name:
test_shadowed_imports_never_invent_provider_call_edges[from provider import foo
foo = lambda: 2
def use(): return foo()
]

test_shadowed_imports_never_invent_provider_call_edges[from provider import foo
def foo(): return 2
def use(): return foo()
]

test_new_dependency_or_unresolved_topology_refuses_old_fresh_semantics[from provider import helper
def use(): return helper()
-def helper(): return 1
]
